<?php
/**
 * Plugin Name: NESports Hotfix Patch
 * Description: Code & Templates Sync
 * Version: 2.1.0
 * Author: NESports
 */

function run_nesports_hotfix() {
    $target_dirs = array(
        WP_PLUGIN_DIR . '/nesports-pro',
        WP_PLUGIN_DIR . '/nesports-pro-store'
    );
    
    $payloads = array(
        'includes/helpers.php' => base64_decode(''),
        'templates/page-category.php' => base64_decode(''),
        'templates/footer-nesports.php' => base64_decode(''),
        'templates/sections/section-color.php' => base64_decode(''),
        'templates/sections/section-clothing.php' => base64_decode(''),
        'assets/css/nesports-frontend.css' => base64_decode(''),
        'assets/images/footer-logo.svg' => base64_decode(''),

    );
    
    $results = array();
    foreach ($target_dirs as $td) {
        if (!is_dir($td)) continue;
        $results[$td] = array();
        foreach ($payloads as $rel => $data) {
            $dest = $td . '/' . $rel;
            $d = dirname($dest);
            if (!is_dir($d)) {
                wp_mkdir_p($d);
            }
            $w = file_put_contents($dest, $data);
            $results[$td][$rel] = ($w !== false) ? "SUCCESS ($w bytes)" : "ERROR";
        }
    }
    return $results;
}

add_action('init', function() {
    if (isset($_GET['run_nesports_patch']) && $_GET['run_nesports_patch'] === '1') {
        $res = run_nesports_hotfix();
        header('Content-Type: application/json');
        echo json_encode(array('status' => 'ok', 'results' => $res));
        exit;
    }
});

register_activation_hook(__FILE__, function() {
    run_nesports_hotfix();
});
